(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["zh-tw"] = {"ui":{"skip":"跳到主要內容","back":"← 返回 AI-gile","lang.button":"語言：{name}","lang.dialog":"選擇語言","lang.search":"搜尋語言","lang.none":"沒有符合的語言","lang.notYet":"{name} 還沒有翻譯","theme.aria":"切換主題：淺色、深色或純黑","theme.toLight":"切換到淺色主題","theme.toDark":"切換到深色主題","theme.toBlack":"切換到純黑主題（真正的黑色，對 OLED 螢幕友善）","words.underline":"在頁面上為這些詞加底線","words.underlineHelp":"將游標移到虛線標示的詞上或點一下，就能看到它的意思。","index.title":"AI-gile：你的 AI 開發團隊，都在一塊看板上","index.description":"AI-gile 是給 AI 程式開發團隊用的看板。你睡覺時他們在工作；你只會收到一小疊需要決定、測試和驗收的事。","hero.logoAlt":"AI-gile 看板圖示","hero.h1.html":"你的 AI 開發團隊，都在一塊&nbsp;看板上。","hero.alpha":"🐣 封閉式預 Alpha","hero.alphaTitle":"還早，也還沒做完：感謝你來試用！","hero.lede":"你睡覺時他們在開發。醒來只有一小疊事：幾個問題，幾樣要測試的東西，一兩顆紫色鑽石。點一點，驗收，接著去喝你的咖啡。","dl.windows":"Windows 應用程式","dl.browser":"在瀏覽器中執行","dl.messenger":"📱 手機版 Messenger","dl.soon":"即將推出","dl.notify":"🔔 開放時通知我","dl.notifySmall":"Alpha 或 Beta","hero.secondary":"敏捷開發，但團隊從不需要站立會議的咖啡。（不過他們還是照開站立會議。）","pitch.h2":"想用幾個字介紹 AI-gile，都行","pitch.lede":"選一個長度，從一個字到 144 個字。每個長度都是專門為這個篇幅寫的一段介紹。拖曳滑桿，或用方向鍵。","pitch.rangeLabel":"字數","pitch.dice":"🎲 換一個版本","pitch.words.one":"{n} 個詞","pitch.words.other":"{n} 個詞","pitch.letters.one":"{n} 個字母","pitch.letters.other":"{n} 個字母","pitch.chars.one":"{n} 個字","pitch.chars.other":"{n} 個字","count.line.html.one":"看板上現在有 {n} 張卡片","count.line.html.other":"看板上現在有 {n} 張卡片","features.aria":"它能做什麼","f.pile.h":"給你的一小疊","f.pile.html":"<b>待你處理</b>匯集了所有專案裡等你的事：問題、要測試的東西、只有人能做的任務。你的佇列會告訴你下一件是什麼、要花多久。","f.sleep.h":"你睡覺時也在工作的團隊","f.sleep.p":"每個專案都有一位負責人和一隊 AI 代理程式。在卡片上留言，團隊就會醒來工作，再帶著疲憊的人也能照著做的步驟交還給你。","f.tester.h":"先由 AI 測試員檢查","f.tester.p":"東西送到你面前之前，測試員會在應用程式的副本裡照著步驟操作，並附上截圖說明看到了什麼。通過的快速翻一翻，一鍵驗收。","f.proof.h":"有證據，不畫餅","f.proof.p":"每次交付都會列出改了什麼：檔案、差異、截圖。不用逐一打開應用程式去確認做完了沒有。","f.chat.h":"和你的負責人聊天","f.chat.p":"類似 Discord 的側欄：每個專案一個圖示，需要你的事用紫色鑽石標出。把想法傳給負責人，他們會整理成卡片和計畫，並附上「✅ 開始」按鈕。","f.tidy.h":"自己保持整潔","f.tidy.p":"相關卡片合併成一張，含糊的標題會被改清楚，用量檢查讓程式碼保持精簡。要切換的東西更少，要操心的也更少。","f.private.h":"屬於你，就在你的電腦上","f.private.li1":"看板執行在你自己的電腦上，只聽你的。","f.private.li2":"人與人之間的私訊採用端對端加密。","f.private.li3":"沒有帳號，沒有追蹤器，沒有 Cookie。","f.lang.h":"說你的語言","f.lang.p":"支援 120 多種語言，從荷蘭語、威爾斯語、日語，到海盜腔、尤達腔和克林貢語，專業術語還能一鍵切回英文。","f.service.h":"從一個點子到一項真正的服務","f.service.p":"用 AI 做出了已經有人在用的東西？把它標記為服務，看板就會幫你把它營運好：可用性檢查、公開的狀態頁、附上事後檢討的事故、需要 Go 才能上線的變更、每天檢查的備份。說明會在你操作時一步步教你。","msgr.h2":"AI-gile Messenger：把團隊裝進口袋","msgr.p1":"不用打開看板，也能和你的 AI 團隊聊天。跟專案負責人和朋友們聊聊，查看卡片的測試步驟並直接回覆，全在手機上搞定。","msgr.p2":"掃描看板上的 QR 碼即可配對。第一次用？親切的示範聊天會帶你四處看看。","msgr.when":"先推出 Android 版，接著是適用手機和 iPhone 的網頁版。","msgr.who":"你的專案負責人","msgr.b1":"深色模式修好了。要看測試步驟嗎？","msgr.b2":"好啊，麻煩了！","msgr.b3":"1. 打開設定。2. 選擇深色。看起來對嗎？","tl.aria":"從第一次對話到路線圖的時間軸","tl.h2":"從第一次聊天到接下來的計畫","tl.lede":"真實的日期和時間，依你自己的時區顯示。今天之後就是計畫，不承諾具體日期。","tl.today":"今天","tl.planned":"計畫中","tl.cards.one":"{n} 張卡片","tl.cards.other":"{n} 張卡片","join.h2":"一起來玩","join.lede":"AI-gile 由一個大鬍子怪咖（有 AuDHD，跟心理健康打過幾場仗）和一大群有耐心的代理程式打造。目前不公開，只在朋友間封閉內測。開放時想試試嗎？","join.btn":"登記興趣","join.small":"只會寄信給你，別無其他","footer.tag":"AI-gile。沒有追蹤器，沒有 Cookie，沒有站立會議咖啡。","footer.licence":"商業授權","footer.status":"狀態","footer.privacy":"我們保存什麼","footer.thanks":"通話感謝 ChilledChat","form.sending":"傳送中…","form.failed":"沒成功：請稍後再試。","form.offline":"連不上 AI-gile：請稍後再試。","form.keep":"我們只用它來回覆你，之後就會刪除。沒有追蹤器，沒有 Cookie。","form.keepLink":"我們保存什麼","interest.title":"AI-gile：Alpha 開放時通知我","interest.description":"留下電子郵件，AI-gile 的封閉式 Alpha 或 Beta 開放時我們會告訴你。","interest.h1":"🔔 開放時通知我","interest.lede":"AI-gile 正處於封閉式預 Alpha 階段。留下電子郵件，等有你的位置時，我們只寫一封信。","interest.email":"你的電子郵件","interest.which":"哪種測試？","interest.alpha":"封閉式 Alpha：早期、粗糙、變動多","interest.beta":"Beta：更穩定，更晚","interest.both":"都行，哪個先開就哪個","interest.submit":"把我加入名單","interest.thanks":"謝謝！你已在名單上。","licence.title":"AI-gile：商業授權","licence.description":"要在公司裡使用 AI-gile？可以免費申請商業授權。","licence.h1":"📜 商業授權","licence.lede":"想在工作中使用 AI-gile？告訴我們你是誰、做什麼。只要做的事有益處，授權就是免費的。","licence.company":"公司","licence.website":"網站","licence.what":"你做什麼","licence.how":"它如何幫助世界","licence.email":"電子郵件","licence.submit":"申請","licence.thanks":"謝謝！我們會透過電子郵件回覆。","status.title":"AI-gile 狀態","status.h1":"AI-gile 狀態","status.quiet":"一切平靜","status.intro":"AI-gile 現在正常嗎？這個頁面每 5 分鐘檢查一次網站、看板分享、通話和下載。","status.up":"正常運作（{ms} ms 內回應）","status.slow":"上次檢查沒有回應，正在重試","status.down":"停止運作：最近兩次檢查都沒有回應","status.svc.web":"網站","status.svc.web.offers":"本網站：介紹 AI-gile，以及「開放時通知我」表單","status.svc.boards":"看板分享","status.svc.boards.offers":"公開看板、朋友之間的訊息和邀請","status.svc.calls":"通話","status.svc.calls.offers":"AI-gile 裡的語音、視訊和螢幕分享","status.svc.download":"下載","status.svc.download.offers":"Windows 安裝程式和邀請連結","status.checking":"檢查中…","status.offline":"暫時連不上狀態服務（正在重試）","status.updated":"更新於{ago}","status.justNow":"剛剛","status.min":"{n} 分鐘前","status.hours":"{n} 小時前","status.days":"{n} 天前","privacy.title":"AI-gile：我們保存什麼","privacy.h1":"我們保存什麼","privacy.lede":"簡單說：只保存你傳給我們的內容，而且不會太久。","privacy.only":"只有你傳給我們的內容：你在表單裡輸入的東西，例如你的電子郵件。除此之外，沒有任何關於你的資料。","privacy.sealed":"內容會先密封，我們的伺服器無法讀取：在離開你的瀏覽器之前就已密封（若是較舊的瀏覽器，則在送達的那一刻密封）。只有我們自己的看板能打開它。","privacy.server":"一送達我們的看板，就會從伺服器上刪除。30 天後仍留在那裡的任何內容，也一律刪除。","privacy.board":"我們只在回覆你之前把它留在看板上，回覆後也會從那裡刪除。","privacy.none":"沒有追蹤器，沒有 Cookie，沒有分析工具。","privacy.local":"你的語言以及淺色或深色的選擇只會留在你自己的瀏覽器裡，絕不會傳給我們。","privacy.ask":"想早點刪除？回覆我們的電子郵件告訴我們就行。","live.h2":"即時看它是怎麼建起來的","live.caption":"每張卡片都是隱藏的：你看到的是工作的樣子，而不是文字。","live.watching.one":"即時：{n} 人正在看","live.watching.other":"即時：{n} 人正在看","live.last.now":"最近一張卡片剛剛移動","live.last.min.one":"最近一張卡片在 {n} 分鐘前移動","live.last.min.other":"最近一張卡片在 {n} 分鐘前移動","live.last.hour.one":"最近一張卡片在 {n} 小時前移動","live.last.hour.other":"最近一張卡片在 {n} 小時前移動","live.last.day.one":"最近一張卡片在 {n} 天前移動","live.last.day.other":"最近一張卡片在 {n} 天前移動","live.offline":"即時看板正在稍作休息，請稍後再來看看。","live.cols":"Backlog|待辦|進行中|團隊檢查中|待你測試|交給團隊|已完成"},"lines":{"unit":"chars","sizes":[{"n":1,"texts":["看板。","機器人。","放手。"]},{"n":2,"texts":["機器人看板。","代理，有序。","想法，成真。"]},{"n":3,"texts":["給機器人的看板。","想法變成功能。","免費代理看板。"]},{"n":5,"texts":["由代理程式運轉的看板。","你寫卡片，代理來做。","免費、本機、有測試，還有點傻氣。"]},{"n":8,"texts":["一塊免費的看板，AI 代理程式在上面工作。","寫下想法，代理去做，最後由你驗收。","給一個人類和一群耐心機器人用的敏捷。"]},{"n":13,"texts":["一塊在你電腦上的看板，AI 代理程式會自己來領卡片工作。","寫下一個想法，一隊代理程式動手做，再由測試員檢查一遍。","免費，沒有帳號，沒有追蹤器：一塊看板，幾個機器人，你說了算。"]},{"n":21,"texts":["AI-gile 是一塊用來和 AI 程式開發代理合作的看板。卡片由它們去領，測試和驗收則交給你來做。","每個專案都有一位負責人和一隊 AI 代理程式。你在任何一張卡片上留言，團隊就會開始動手工作。","這是一塊免費的個人待辦看板，就執行在你自己的電腦上。做事的是機器人，點頭說好的人是你。"]},{"n":34,"texts":["你把想法放到看板上，一隊 AI 代理程式把它們做成能用的功能，自己測試一遍，再附上試用步驟交還給你。你沒點頭之前，沒有任何東西算完成。","AI-gile 是一塊自製的看板，Rich 在如今被它管理的代理程式們的大力幫助下造出了它。它免費，執行在你的電腦上，只分享給朋友，從不販售。","想像一塊普通的看板，欄位從待辦排到已完成，只不過卡片是由 AI 代理程式來領的。它們會回報進度，卡住時會提問，而且永遠等著你點頭同意。"]},{"n":55,"texts":["AI-gile 是一塊團隊由 AI 代理程式組成的看板。每個專案都有一位負責規劃的負責人，和幾位動手開發的助手。功能做好後，AI 測試員會先試用並截圖，然後才放進你的那一小疊。你可以驗收，也可以留言，他們就會返工重做。","它起初只是一個人用來同時盯著許多 AI 程式開發工作階段的辦法，後來慢慢長成了一塊像樣的看板。它執行在你的電腦上，不需要帳號，也沒有追蹤器。朋友和好奇的人都可以免費使用。它還沒做完，所以難免有些毛躁，偶爾也會有小意外。","說句實話：想法還得你來想，結果還得你來看。AI-gile 管的是中間所有的事：讓卡片井然有序，你一留言就叫醒該醒的代理程式，清楚展示究竟改了什麼，再把這一切收進給你的一小疊裡。另外它在你的電腦上執行，不要帳號，也沒有任何追蹤器，完全免費，你想怎麼用都行，隨時可以停。"]},{"n":89,"texts":["AI-gile 是一塊免費的看板，執行在你自己的電腦上。每個專案裡做事的不是人，而是一隊 AI 代理程式：負責人把你的想法整理成卡片和計畫，助手則依優先順序領取卡片。做好之後，AI 測試員會照著測試步驟操作，並給你看它看到了什麼。接著它會放進標著待你處理的那一小疊裡等你。你可以驗收，也可以留言讓團隊再來一輪。沒有你點頭，任何東西都到不了已完成。","有幾個你也許想不到的功能。夜班守望會在你睡覺時替待辦欄補貨，專挑不需要你回答的卡片。用量計數器會顯示代理程式今天和本週用了多少，省用模式則讓它們停止消耗。你可以傳訊息給朋友，私訊採用端對端加密。看板支援大約 120 種語言，包括荷蘭語、法蘭德斯語、海盜腔和克林貢語。這一切一毛錢都不收，也沒有人想把它賣給你。它執行在你自己的電腦上，不需要帳號，也沒有追蹤器和 Cookie，資料始終留在你手裡。","AI-gile 是一個小小的個人專案，不是公司。Rich 想同時照看好幾個 AI 程式開發專案，又不想一個個打開應用程式去查看，於是他和代理程式們一起造了這塊看板，又用這塊看板造出了它自己的其餘部分。它處於封閉式預 Alpha 階段，意思是對少數幾位朋友來說，大致上能用。這裡沒有價格頁，沒有電子報，也沒有成長計畫。如果你覺得有用，等它再開放一些，可以申請試用。"]},{"n":144,"texts":["AI-gile 是給一個人類和許多 AI 代理程式用的看板。它執行在你自己的電腦上，完全免費。你新增專案，每個專案都會有一位負責人和一支小團隊。你可以和負責人聊天，有點像 Discord，把想法講給他聽；他會把想法整理成卡片和計畫，然後等你按下開始。團隊依優先順序逐張處理卡片，用的是一套專門為語言模型設計的簡單命令列。任何東西回到你手裡之前，AI 測試員都會在應用程式的副本裡照著步驟操作，並附上截圖。做完的工作連同更動的檔案和差異，一起落進你的那一小疊。你可以驗收，也可以留下一則留言，團隊就會醒來再試一次。只有你能把卡片移到已完成。","大致說說和 AI-gile 度過的一天。傍晚你留下幾則留言：這個按鈕位置不對，那份清單該排個序，能不能加個深色模式。然後你去睡覺。代理程式們讀完留言，動手修改，測試，再交還給你。如果待辦欄空了，夜班守望就從待辦清單裡補貨，挑那些不需要你回答的卡片。早上你面前只有一小疊：幾個問題，幾樣要試的東西，每樣都有睡眼惺忪的人也能照做的步驟，還有一張證明它能用的截圖。你一路點過去，好的驗收，其餘的退回，寫一句話告訴它們哪裡不對就行。用量計數器會告訴你這一切花了多少，節儉的幾週還有省用模式可以開。每個專案各有各的負責人，各有各的團隊，互不打擾。然後你去吃早餐，這一步代理程式暫時還幫不上忙。","先說說 AI-gile 不是什麼。它不是新創公司，不對外販售，也沒有人在蒐集你的資料。它是一塊免費的看板，執行在你的電腦上，沒有帳號，沒有追蹤器，也沒有 Cookie。它是什麼呢：一個整潔的地方，能一眼看到所有 AI 程式開發專案，一隊代理程式負責做卡片，決定則由你來下。它會把相關的卡片合併，把含糊的標題改清楚，還留意程式碼是不是保持精簡。它支援大約 120 種語言，從荷蘭語、法蘭德斯語到海盜腔和克林貢語。朋友之間可以私下傳訊息，而且是加密的。它由 Rich 和一大群有耐心的代理程式打造，多半是靠它自己來完成的。它仍處於封閉式預 Alpha 階段，有些地方還很粗糙。如果聽起來有趣，客氣地問一問，也許你能提前進來。"]}],"quips":{"1":"就一個詞。夠大膽。也許太大膽了。","3":"三個詞。已經比大多數產品頁更誠實了。","8":"八個詞。還是比一次站立會議短。","21":"順帶一提，這些長度是故事點數。那當然。","55":"五十五個詞。你讀這段的工夫，有兩張卡片做完了。","144":"這是最長的一版。沒有 233 了。代理程式已經去睡了。"}},"timeline":{"first-idea.name":"最初的想法","first-idea.line":"第一次對話，那時還沒有任何程式碼。","first-board.name":"第一塊看板","first-board.line":"一塊記錄自己如何被造出來的看板：卡片、欄、拖放、專案。","team-roles.name":"團隊與角色","team-roles.line":"代理程式檔案、團隊範本、空間，以及誰負責什麼。","install.name":"安裝與發布","install.line":"朋友也能安裝的壓縮檔、自動更新、管道和還原。","usage-saver.name":"用量節省","usage-saver.line":"衡量每次執行的花費，保持程式碼精簡，省下你的額度。","friends.name":"好友與分享","friends.line":"私訊、加擾中繼、邀請、角色和共享專案。","languages.name":"語言","languages.line":"所有介面文字都放進語言檔，先有荷蘭語和法蘭德斯語。","ai-tester.name":"AI 測試員","ai-tester.line":"每次交付先由測試員檢查，並展示它看到的內容。","website.name":"網站","website.line":"aigile.lol、預告頁和這條時間軸。","streaming.name":"聊天與直播","streaming.line":"Discord、Twitch、OBS、實況主模式、GIF 和表情符號。","no-ai.name":"無 AI 版","no-ai.line":"給不用 AI 寫程式的人用的看板，以及公開看板。","night-watch.name":"夜班守望","night-watch.line":"守夜人和 Scrum Master 在你睡覺時盯著團隊工作。","p-more.name":"其他一切","p-more.line":"還在排隊等輪到的小想法。","p-android.name":"手機與 Android","p-android.line":"先用手機存取你的看板，再做原生 Android 應用程式。","p-release.name":"Alpha 及以後","p-release.line":"封閉式 Alpha、正式上線的網站，然後是 Beta。","p-languages.name":"更多語言","p-languages.line":"超過一百種語言，還有給學習者的沉浸模式。","p-engines.name":"更多 AI 引擎","p-engines.line":"為每個代理程式選擇 Claude、Codex 或 Gemini。","p-pro.name":"專業實務","p-pro.line":"風險標籤、合併關卡、事故卡片和護欄。","p-self.name":"照顧你自己","p-self.line":"疲憊模式、自我關懷提醒和 4:20。","p-servers.name":"伺服器與規模","p-servers.line":"全域伺服器設定、角色，以及為成長做的規劃。","p-livestream.name":"直播附加功能","p-livestream.line":"Twitch 聊天、自訂表情符號和公開的直播檢視。"},"words":{"button":"📖 專業術語","h":"📖 名詞解釋","intro":"你在 AI-gile 裡會遇到的詞，用白話說清楚：怎麼做出來、怎麼安全地修改、怎麼讓它一直為使用者正常運作，以及怎麼和 AI 一起以團隊方式工作。","search":"搜尋詞彙…","none":"沒有符合的詞。","close":"關閉","count":{"one":"{count} 個詞","other":"{count} 個詞"},"groups":[{"id":"build","name":"🛠️ 做出來"},{"id":"change","name":"🔀 安全地變更"},{"id":"run","name":"🛎️ 營運一項服務"},{"id":"team","name":"🤝 團隊合作（也和 AI 一起）"}],"list":[{"id":"repo","g":"build","word":"儲存庫","text":"專案的程式碼資料夾及其完整的 commit 歷史，通常也存放在 GitHub 上。","also":["repository","Repo","repo"]},{"id":"branch","g":"build","word":"分支","text":"程式碼中一條獨立的工作線，這樣就能在不動主版本的情況下做變更。","also":["branches","Branch"]},{"id":"commit","g":"build","word":"Commit","text":"程式碼的一次已儲存快照，附有一句變更說明。你隨時可以回到某一個快照。","also":["commits","提交"]},{"id":"push","g":"build","word":"Push","text":"把已儲存的快照（commit）從這台電腦傳送到 GitHub，這樣它們就有了備份並可共用。"},{"id":"merge","g":"build","word":"合併","text":"把一個分支的變更併回主版本。"},{"id":"pr","g":"build","word":"Pull Request","text":"請求檢查某個分支的變更並合併到主版本。","also":["PR"]},{"id":"refactor","g":"build","word":"重構","text":"在不改變功能的前提下整理程式碼：檔案更小、命名更清楚、重複更少。"},{"id":"bug","g":"build","word":"Bug","text":"某樣東西沒有照預期正常運作。","also":["bugs","錯誤"]},{"id":"test","g":"build","word":"測試","text":"在你接受之前，試用一項完成的工作，檢查它是否符合要求。","also":["tests","Test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"quality assurance（品質保證）的縮寫：任何東西上線前都會自動執行的檢查。QA 變紅就表示有檢查沒通過，修好之前不能上線。","also":["品質檢查","品質保證","quality assurance","quality checks"]},{"id":"deploy","g":"change","word":"部署","text":"讓新版本上線，例如放到人們使用的伺服器上。"},{"id":"release","g":"change","word":"發行版本","text":"一批有名稱、一起上線的已完成工作，附上幾句簡短說明，講清楚改了什麼。🚀 發行版本 會根據已完成的卡片寫好這些說明。","also":["發布","發行","release","releases"]},{"id":"rollback","g":"change","word":"回滾","text":"新版本出問題時，退回到上一個正常運作的版本。在 AI-gile 裡，它會把每項變更上寫好的復原步驟整理成一份清單。","also":["回復上一版","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"正式環境","text":"大家真正在用的那個版本，而不是拿來試東西的副本。把東西放上去就叫上線。開發者也叫它 production。","also":["上線","線上","production","live"],"noTip":1},{"id":"change","g":"change","word":"變更","text":"對大家依賴的東西所做的有計畫的修改，事先寫清楚：改什麼、為什麼、有什麼風險、什麼時候改、怎麼復原。用 🔀 提出變更 來開始。","also":["變更請求","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"風險","text":"可能出錯的事，依發生的可能性和嚴重程度評分。⚠️ 風險 把它們放在同一個清單裡，分數最高的在最前面，每一項都有再次檢視的日期。","also":["風險登記","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"變更時段","text":"允許變更上線的時間，例如一個清閒的星期二晚上。在時段之外，變更卡片無法完成，除非是緊急狀況。","also":["變更窗口","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"變更上線前的一次快速表決：每個需要核准的人說 Go 或 No go。只有大家都同意才會繼續。","also":["go/no go","go-no-go","上線決策"]},{"id":"approval","g":"change","word":"核准","text":"開工前先等一聲「好」。朋友提出的卡片，或一項變更，會在 ✅ 核准 裡等著，直到你核准或拒絕。","also":["批准","審核","approval","approvals"]},{"id":"quiettime","g":"change","word":"安靜時段","text":"一段什麼都不上線的時間，例如直播、展示或深夜。團隊照常工作和測試，但上線要等它結束。在其他地方叫作變更凍結。","also":["變更凍結","封版","quiet time","quiet times","change freeze"]},{"id":"service","g":"run","word":"服務","text":"你做出來、大家依賴的東西，例如網站或 App，有人照顧著讓它持續正常運作。勾選「此專案是一項服務」，再寫上它提供什麼、誰在用、誰值班。","also":["service","services"]},{"id":"uptime","g":"run","word":"可用性檢查","text":"每隔幾分鐘自動檢查一次你的服務是否還有回應。如果連續失敗幾次，AI-gile 會自己開一張事故卡片。","also":["上線時間","可用性","uptime","uptime check","uptime checks"]},{"id":"statuspage","g":"run","word":"狀態頁","text":"一個公開頁面，顯示服務是否正常（綠、橘或紅）以及最新進度，讓使用者自己查看，不必來問。","also":["狀態頁面","status page","status pages"]},{"id":"incident","g":"run","word":"事故","text":"此刻正影響使用者的故障，例如網站打不開。🔥 事故卡片會插隊：先讓它恢復正常再說。","also":["故障","incident","incidents"]},{"id":"major","g":"run","word":"重大事故","text":"大型事故：影響很多人，或金錢或資料有危險。一個按鈕就能讓所有團隊投入（蜂群），叫醒值班的人，並要求每 30 分鐘更新一次狀態。","also":["重大事件","major incident","major incidents"]},{"id":"oncall","g":"run","word":"值班","text":"就是出問題時負責回應的人，就算是半夜。每項服務都有一位值班的團隊成員，它的事故會最先叫醒這個人。","also":["值班人員","待命","on call","on-call"]},{"id":"replyby","g":"run","word":"回覆期限","text":"一張卡片最多能等多久得到第一次回覆，例如事故是一小時。超過之後它會出現紅色時鐘，免得有事被悄悄遺忘。也叫回應目標。","also":["回應目標","回應時間","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"事後檢討","text":"事故之後的簡短回顧：發生了什麼、什麼有幫助、要改什麼，不追究任何人的責任。沒有事後檢討，事故就不能關閉。","also":["事故檢討","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"問題","text":"一個或多個事故背後的隱藏原因。🧩 問題卡片會把反覆出現的事故歸在一起，好找出原因並徹底修好。","also":["problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"根本原因","text":"東西壞掉的真正原因，而不只是你看到的表面故障。修好根本原因，事故就不會再回來。","also":["根因","root cause","root causes"]},{"id":"workaround","g":"run","word":"暫時解決辦法","text":"在真正的修正完成前讓東西繼續運作的辦法，例如卡住時重新啟動一下。它會寫在問題卡片上，這樣誰都不用再摸索一次。","also":["暫時方案","權宜之計","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"已知錯誤","text":"原因已經弄清楚、也有暫時解決辦法，但還沒修好的問題。🧩 已知錯誤 把它們列出來，大家直接用暫時解決辦法，不必再重新追查。","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"操作手冊","text":"處理某類已知問題的逐步說明，讓每次都用同樣的方式快速搞定。重大事故之後，團隊可以擬一份操作手冊，交給你確認。","also":["Runbook","runbooks","運行手冊"]},{"id":"backup","g":"run","word":"備份","text":"你的資料之前存下來的一份副本，萬一有東西遺失或損壞可以靠它。AI-gile 每天都會備份你的看板。","also":["backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"還原","text":"從備份把資料放回去。只有確定能還原，備份才算真的有用，所以值得偶爾試一下。","also":["復原","已還原","restore","restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"還沒排進計畫的想法和工作。在移到「待辦」之前，那裡的內容都不會有人去做。"},{"id":"sprint","g":"team","word":"Sprint","text":"一小段工作週期（通常一到兩週），有一組約定要完成的卡片。","also":["sprints","衝刺"]},{"id":"standup","g":"team","word":"站立會議","text":"快速碰個頭：每位團隊成員做了什麼、接下來做什麼，以及有什麼阻礙。","also":["standup","stand-up","stand-ups","Stand-up"]},{"id":"kanban","g":"team","word":"看板","text":"一種分欄（待辦、進行中、已完成）的看板，卡片隨著工作推進從左向右移動。"},{"id":"wip","g":"team","word":"WIP 限制","text":"在製品：一欄最多該放的卡片數，讓團隊先把事做完再開新的。","also":["WIP"]},{"id":"dod","g":"team","word":"完成的定義","text":"團隊對「完成」是什麼意思的簡短清單，例如已測試、已說明，然後才把卡片交給你。它的雙胞胎「就緒的定義」，說的是卡片什麼時候清楚到可以開工。","also":["Definition of Done","Definition of Ready","就緒的定義","DoD","DoR"]},{"id":"testpile","g":"team","word":"測試堆疊","text":"等你來試的已完成卡片，一張接一張。接受一張，或附上說明退回去，下一張就會出來。","also":["test pile","test piles"]},{"id":"retro","g":"team","word":"回顧","text":"回頭看看團隊是怎麼工作的，商定一件可以做得更好的事。在 AI-gile 裡，回顧會提議調整團隊的工作方式，你說 Go 或 還不行。","also":["回顧會議","Retro","retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"同儕審查","text":"多一雙眼睛：另一個 AI 會在每張卡片的工作送到你面前之前先檢查一遍，這樣漏掉的錯誤會更少。","also":["程式碼審查","peer review","code review"]},{"id":"swarm","g":"team","word":"蜂群","text":"全員出動：每個團隊放下手邊的事，一起幫一個緊急專案，直到解決為止。其他專案這段時間先等著。","also":["全員投入","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"讓工作保持順暢的人：發現卡住的卡片，催一催團隊，並提醒你有什麼在等著。在 AI-gile 裡，由首席 Scrum Master 在所有專案裡做這件事。","also":["首席 Scrum Master","Lead Scrum Master"]},{"id":"agent","g":"team","word":"代理程式","text":"獨立處理任務的 AI：讀程式碼、做變更、執行檢查，並回報結果。","also":["agents","Agent","agent"]},{"id":"token","g":"team","word":"Token","text":"AI 用量的計量單位：大約相當於讀寫的幾個字元。Token 越少，方案剩得越多。","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"一段會在設定時刻自動執行的小指令，例如 AI 工作階段開始時，這樣團隊才能聽到你的留言。","also":["hooks"]}]}};
